contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address receiver, uint amount) public payable {
        uint beforeBal = address(c).balance;

        bool reverted;
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBal = address(c).balance;

        // The only failure mode is the owner's transfer reverting, which forces
        // amount <= beforeBal (EVM balance check), so after the try/catch:
        //  - if it reverted, c's balance is unchanged;
        //  - if it succeeded, c's balance decreased by exactly amount.
        assert(reverted ? afterBal == beforeBal : afterBal + amount == beforeBal);
    }
}

